<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class MissingDocument extends Model { protected $fillable=['proposal_id','description','evaluation_status','moa_check','created_by']; public function proposal():BelongsTo{return $this->belongsTo(Proposal::class)->withTrashed();} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by')->withTrashed();} }